PRAGMA page_size=1024; CREATE TABLE t1(a INTEGER, b INTEGER, c TEXT); WITH RECURSIVE seq(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM seq WHERE i<50000) INSERT INTO t1 SELECT i, (i*214013+2531011)%500000, printf('number %d',(i*134775813+1)%500000) FROM seq; CREATE INDEX i1a ON t1(a); CREATE INDEX i1b ON t1(b); CREATE INDEX i1c ON t1(c);